sys_ui_action.script:
function createDocument() {


    var inputs = {};

    inputs['incidentid'] = g_form.getUniqueValue(); // String 

    GlideFlow.startSubflow('sn_itsm_gen_ai.rca_document_generator', inputs)
        .then(function(execution) {
            return execution.awaitCompletion();
        }, errorResolver)
        .then(function(completion) {

            var status = completion.status;

            // Available Outputs:
            var outputs = completion.outputs;
            var probsysid = outputs['probsysid']; // String		
            var problemnumber = outputs['problemnumber']; // String		
            var rcaanalysis = outputs['rcaanalysis']; // String		
            var resolutiontaken = outputs['resolutiontaken']; // String		
            var nextsteps = outputs['nextsteps']; // String		
            var preventivemeasures = outputs['preventivemeasures']; // String

            g_form.addInfoMessage('RCA Analysis ' + rcaanalysis);




            var generateRACDocument = new GlideAjax('global.synergizeGlobalUtils');
            generateRACDocument.addParam('sysparm_name', 'generateDocument');
            generateRACDocument.addParam('sysparm_problemRec', probsysid);
            generateRACDocument.addParam('sysparm_relatedIncidents', g_form.getUniqueValue());
            generateRACDocument.addParam('sysparm_rcaAnalaysis', rcaanalysis);
            generateRACDocument.addParam('sysparm_resolutionTaken', resolutiontaken);
            generateRACDocument.addParam('sysparm_nextSteps', nextsteps);
            generateRACDocument.addParam('sysparm_preventiveMeasures', preventivemeasures);

            generateRACDocument.getXMLAnswer(function(response) {
                //g_form.clearMessages();

                g_form.addInfoMessage(response);
                if (response == 'success') {
					g_form.clearMessages();
					g_form.addErrorMessage('RCA Document attached to problem. Please refer to ' + '<a target="_blank" href="/nav_to.do?uri=problem.do?sys_id=' + probsysid + '">' + problemnumber + '</a>');

                    return;
                }



            });



        });

    function errorResolver(error) {
        // Handle errors in error resolver
    }




}


function escapeHtml(value) {
    return String(value || '')
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#039;');
}
